    public static function key(string $source):string{return 'contribution_delivery_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];foreach(self::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;return $messages;
    }
    public static function text(string $source,array $messages):string{return $messages[self::key($source)]??ContributionMessages::text($source,$messages);}
    public static function reason(string $source,array $messages):string
    {
        foreach(['Bewusst erneut vorgemerkt. ','Vormerkung bewusst angehalten. ','Unterbrochener Versand zur Klärung vorgemerkt. ','Nichtversand anhand Nachweis manuell bestätigt. ','Versand anhand Nachweis manuell bestätigt. ']as$prefix)if(str_starts_with($source,$prefix))return self::text($prefix,$messages).substr($source,strlen($prefix));return self::text($source,$messages);
    }
